'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('zh-CN',{style:'currency',currency:'CNY'}).format(n/100);
const stamp=s=>s?new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'—';
const S={user:null,csrf:'',tab:'members',members:[],stores:[],employees:[],users:[],filter:'all',query:'',register:false,setupToken:location.hash.slice(1),recharges:{records:[],groups:[],total:0},filters:{}};
if(location.hash)history.replaceState(null,'',location.pathname);
async function api(path,data){const r=await fetch(path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json','X-CSRF-Token':S.csrf}:{},body:data?JSON.stringify(data):undefined});const d=await r.json();if(!r.ok){if(r.status===401&&S.user){S.user=null;$('#modal').close();authView();}throw Error(d.error||'操作失败');}return d;}
window.addEventListener('beforeunload',e=>{if($('#modal')?.open&&S.dirty){e.preventDefault();e.returnValue='';}});
let timer;function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;clearTimeout(timer);timer=setTimeout(()=>$('#toast').hidden=true,6500);}
function formError(form,e){let el=form.querySelector('.error');if(!el){el=document.createElement('div');el.className='error';el.setAttribute('role','alert');form.prepend(el);}el.textContent=e.message;}
function option(value,label,selected){return `<option value="${esc(value)}"${value===selected?' selected':''}>${esc(label)}</option>`;}
function storeOptions(selected,blank=true){return (blank?option('','请选择门店',selected):'')+S.stores.filter(x=>x.active).map(x=>option(x.id,x.name,selected)).join('');}
function employeeOptions(store,selected,blank=true){return (blank?option('','请选择员工',selected):'')+S.employees.filter(x=>x.active&&(!store||x.store_id===store)).map(x=>option(x.id,x.name+(store?'':` · ${S.stores.find(s=>s.id===x.store_id)?.name||''}`),selected)).join('');}
function canManage(){return isAdmin()||S.user?.role==='manager';}
function isAdmin(){return S.user?.role==='admin';}
function openModal(title,body){$('#modal-body').innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button type="button" data-close aria-label="关闭">×</button></div>${body}`;S.dirty=false;$('#modal-body').oninput=()=>S.dirty=true;$('#modal').showModal();$('#modal [data-close]').onclick=closeModal;}
function closeModal(){if(!S.saving&&(!S.dirty||confirm('尚未提交，关闭会丢失本次填写内容。确定关闭？')))$('#modal').close();}
function bindForm(id,fn){const form=$(id);form.onsubmit=async e=>{e.preventDefault();const submit=form.querySelector('button[type=submit]');if(submit.disabled)return;submit.disabled=true;S.saving=true;try{await fn(Object.fromEntries(new FormData(form)),form);}catch(e){formError(form,e);}finally{submit.disabled=false;S.saving=false;}};}
async function boot(){try{const d=await api('/api/bootstrap');if(d.version!=='2026.09.24.2'){$('#app').innerHTML='<section class="auth"><h1>请重启会员台以完成升级</h1><p>请停止旧服务，从项目目录运行 python3 start.py，然后刷新本页。升级前请自行完成数据库备份。</p></section>';return;}S.registrationStores=d.registration_stores||[];S.recovery=d.password_recovery||{method:'sms',available:false};S.setup=d.setup;if(S.user?.id!==d.user?.id){S.reportStarted=false;S.filters={};}S.user=d.user;S.csrf=d.csrf||'';S.remote=d.remote_configured;if(S.user)await load();else authView();}catch(e){$('#app').innerHTML=`<div class="auth"><h1>暂时无法连接会员台</h1><p class="error">${esc(e.message)}</p><p>请打开本机文件夹中的“启动会员台.command”。</p></div>`;}}
function authView(){const setup=S.setup,reg=S.register&&!setup;$('#app').innerHTML=`<section class="auth"><header class="brand auth-brand"><b aria-hidden="true">会</b><div><h1>${setup?'首次设置':reg?'员工注册':'会员台'}</h1><small>Best Dream</small></div></header><p class="sub">${setup?'建立管理员账号与第一家门店。客户资料保存在这台主机。':reg?'填写你在百居易使用的前厅账号，并设置会员台独立密码。管理员核实身份及前厅角色、分配门店后即可登录。':'使用你的会员台账号与独立密码登录。'}</p>${S.authMessage?`<p class="warning" role="status">${esc(S.authMessage)}</p>`:''}<form id="auth-form" class="form">${setup||reg?'<label class="field">真实姓名<input name="name" required maxlength="50" autocomplete="name"></label>':''}<label class="field">${reg?'百居易前厅登录账号':'账号'}<input name="username" required minlength="3" maxlength="40" pattern="[A-Za-z0-9_.@-]{3,40}" placeholder="${reg?'与百居易登录账号一致':'英文字母或手机号'}" autocomplete="username"></label><label class="field">${reg?'设置会员台独立密码':'会员台密码'}<input name="password" required type="password" minlength="${setup||reg?10:1}" maxlength="128" autocomplete="${setup||reg?'new-password':'current-password'}" placeholder="${setup||reg?'至少 10 个字符':''}"></label>${reg?'<label class="field">再次输入会员台密码<input name="password_confirmation" type="password" required minlength="10" maxlength="128" autocomplete="new-password"></label><p class="sub">请另设会员台密码，不要填写百居易密码。前厅角色由管理员人工核实，系统不会自动同步百居易权限。</p>':''}${reg?`<label class="field">申请加入门店 *<select name="store_id" required><option value="">请选择门店</option>${(S.registrationStores||[]).map(x=>option(x.id,x.name,'')).join('')}</select></label>`:''}${setup?'<label class="field">第一家门店名称<input name="store" required maxlength="50" placeholder="填写真实门店名称"></label>':''}<button type="submit" class="primary">${setup?'创建管理员':reg?'提交注册申请':'登录'}</button></form>${!setup?`<div class="auth-secondary"><div><span>${reg?'已有账号？':'首次使用？'}</span><button id="auth-toggle" type="button" class="auth-link">${reg?'返回登录':'员工注册'}</button></div>${reg?'':'<button id="forgot" type="button" class="auth-link auth-link-muted">忘记密码</button>'}</div>`:''}${!setup?`<details class="login-help"><summary>登录与注册帮助</summary><ol><li>点击“员工注册”，填写真实姓名、与百居易一致的前厅登录账号。</li><li>设置会员台独立密码（至少 10 个字符），再次输入后提交。</li><li>告知管理员核实前厅身份并分配门店；审批通过后，在本页登录，无需重复注册。</li></ol><p><strong>百居易不能直接登录会员台。</strong>目前没有单点登录，百居易密码和 OpenAPI 令牌不能用于此处登录；同名账号也不会自动获得权限。</p><p>已有会员台账号请直接登录。忘记密码请联系管理员协助；短信找回尚未开通。请勿把密码发到工作群。</p></details>`:''}<p class="foot auth-footer">员工工作入口 · 请使用本人账号</p></section>`;
if($('#forgot'))$('#forgot').onclick=forgotDialog;if(!setup)$('#auth-toggle').onclick=()=>{S.register=!S.register;authView();};bindForm('#auth-form',async(data)=>{if(reg&&data.password!==data.password_confirmation)throw Error('两次输入的会员台密码不一致');delete data.password_confirmation;if(setup)data.setup_token=S.setupToken;const d=await api(setup?'/api/setup':reg?'/api/register':'/api/login',data);if(setup||reg){toast(d.message);S.authMessage=d.message;S.register=false;}await boot();});}
async function load(){const [a,b,ranking]=await Promise.all([api('/api/members'),api('/api/catalog'),api('/api/recharge-leaderboard').catch(()=>({unavailable:true}))]);S.ranking=ranking;S.members=a.members;S.stores=b.stores;S.employees=b.employees;if(S.tab==='performance'){if(!S.reportStarted){S.filters=canManage()?{}:{employee:S.user.employee_id};S.reportStarted=true;}await loadRecharges();S.refunds=(await api('/api/refunds')).requests;}S.auto=await api('/api/member-orders');if(S.tab==='pms'&&isAdmin())S.pms=await api('/api/pms/status');if(S.tab==='settings'&&canManage())S.users=(await api('/api/users')).users;render();}
async function loadRecharges(){S.recharges=await api('/api/recharges?'+new URLSearchParams(S.filters));}
function rechargeRanking(){
 const board=S.ranking||{unavailable:true},leaders=board.leaders||[],labels=['冠军','亚军','季军'];
 const period=board.period?`${Number(board.period.slice(5))}月 · 全门店`:'全门店';
 const entries=Array.from({length:3},(_,index)=>leaders[index]||{rank:index+1});
 return `<aside class="recharge-ranking" aria-label="本月员工充值排行榜"><div class="ranking-heading"><h2>本月充值榜</h2><span>${esc(period)}</span></div>${board.unavailable?'<p class="ranking-empty">榜单暂未更新，请稍后刷新。</p>':`<ol class="ranking-list">${entries.map(person=>{const tied=leaders.filter(p=>p.rank===person.rank).length>1;return `<li><span class="ranking-medal rank-${person.rank}">${tied?'并列':''}${labels[person.rank-1]}</span><div class="ranking-person"><strong>${esc(person.employee||'虚位以待')}</strong><small title="${esc(person.store||'')}">${esc(person.store||'暂无净充值业绩')}</small></div><span class="ranking-amount">${person.employee?money(person.amount):'—'}</span></li>`;}).join('')}</ol>`}<p class="ranking-help" title="北京时间自然月，按充值及已完成充值退款的发生时间统计；上门客户、练习记录不参榜。同额并列，最多展示3人。">本月净充值 · 已扣充值退款 · 同额并列</p></aside>`;
}
function render(){const active=S.members.filter(m=>!m.deleted_at&&!m.practice),month=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Shanghai',month:'2-digit'});if((S.tab==='settings'&&!canManage())||(S.tab==='pms'&&!isAdmin()))S.tab='members';if(S.filter==='practice'||(!isAdmin()&&S.filter==='deleted'))S.filter='all';$('#app').innerHTML=`<main class="shell"><header class="mast"><div class="brand"><b>会</b><div>会员台<small>Best Dream</small></div></div><div class="mast-tools">${rechargeRanking()}<details class="account-menu"><summary>我的账户 <span aria-hidden="true">⌄</span></summary><div class="account-card"><strong>${esc(S.user.name)}</strong><p>${esc(S.stores.find(s=>s.id===S.user.store_id)?.name||'未分配门店')}</p><small>${isAdmin()?'管理员':S.user.role==='manager'?'店长':'前厅员工'}</small><div class="account-actions"><button id="password">修改密码</button><button id="logout">退出登录</button></div></div></details></div></header><nav class="nav" aria-label="工作导航">${[['members','会员档案'],['performance','充值与业绩'],...(canManage()?[['settings',isAdmin()?'管理设置':'门店管理']]:[])].map(([k,n])=>`<button data-tab="${k}" class="${S.tab===k||k==='settings'&&S.tab==='pms'?'active':''}" aria-current="${S.tab===k?'page':'false'}">${n}</button>`).join('')}</nav><div id="view"></div><footer class="foot app-footer"><span>酒店会员服务</span><span>每笔收支，清晰记录</span></footer></main>`;
$$('[data-tab]').forEach(b=>b.onclick=async()=>{S.tab=b.dataset.tab;try{await load();}catch(e){toast(e.message);}});$('#logout').onclick=async()=>{await api('/api/logout',{});await boot();};$('#password').onclick=passwordDialog;
if(S.tab==='members'){const birthdays=active.filter(m=>m.birthday.slice(5,7)===month).length;$('#view').innerHTML=`<div class="headline"><div><h1>会员管理</h1><p class="sub">查找会员、办理充值，随时核对余额。</p></div><button id="new-member" class="primary">＋ 新增会员</button></div><section class="balance-overview" aria-label="会员储值余额"><div><span>会员储值余额</span><p>全部有效会员当前可用余额</p></div><strong>${money(active.reduce((s,m)=>s+m.balance,0))}</strong></section>${memberNotice()}${paymentGuide()}<section class="panel member-panel"><div class="panel-heading"><div><h2>会员档案</h2><p class="sub">充值在会员台，房费储值消费在百居易。</p></div><div class="member-heading-actions"><button id="payment-records" class="quiet">消费同步记录</button><button id="auto-refresh" class="quiet" aria-label="刷新同步结果和会员余额">刷新余额</button></div></div><div class="toolbar"><div class="segments">${[['all',`全部会员 ${active.length}`],['birthday',`本月生日 ${birthdays}`],...(isAdmin()?[['deleted','已删除']]:[])].map(([k,n])=>`<button data-filter="${k}" aria-pressed="${S.filter===k}" class="${S.filter===k?'active':''}">${n}</button>`).join('')}</div><input id="search" type="search" placeholder="输入姓名或手机号查找会员" aria-label="搜索会员" value="${esc(S.query)}"></div><div id="member-table"></div></section>`;$('#new-member').onclick=()=>memberDialog();$('#search').oninput=e=>{S.query=e.target.value;memberTable();};$$('[data-filter]').forEach(b=>b.onclick=()=>{S.filter=b.dataset.filter;render();});memberTable();bindAuto();$('#payment-records').onclick=()=>showPaymentRecords();if($('#show-issues'))$('#show-issues').onclick=showMemberIssues;}
if(S.tab==='performance')performanceView();if(S.tab==='settings')settingsView();if(S.tab==='pms'){pmsView();$('#view').insertAdjacentHTML('afterbegin','<button id="back-settings" class="quiet">← 返回管理设置</button>');$('#back-settings').onclick=async()=>{S.tab='settings';try{await load();}catch(e){toast(e.message);}};}}
function memberNotice(){const p=S.auto||{},count=p.counts?.blocked||0,stale=p.enabled&&(!p.last_scan||Date.now()-Date.parse(p.last_scan)>180000);if(!count&&!p.error&&p.enabled&&!stale)return '';const message=count?`有 ${count} 笔储值消费需要核对`:!p.enabled?'储值消费同步已暂停':p.error?'储值消费同步暂时异常':'储值消费同步尚未更新';return `<aside class="service-notice" role="status"><div><strong>${message}</strong><p>请查看具体原因，确认自动扣款或取消退回是否完成。${!count?'可联系管理员处理。':''}</p></div>${count?'<button id="show-issues">查看问题</button>':''}</aside>`;}
function showMemberIssues(){openModal('待处理的储值消费',`<p class="sub">请按每笔订单的提示处理：订单信息有误，到百居易修改；余额不足，先核实是否需要充值。整单取消后不再扣款，自动已扣余额会在核对取消后退回。处理后等待系统重新核对。</p>${issueCards()}`);bindIssueReviews();}

function $$(s){return Array.from(document.querySelectorAll(s));}
function memberTable(){const month=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Shanghai',month:'2-digit'});const data=S.members.filter(m=>(S.filter==='deleted'?m.deleted_at:!m.deleted_at&&(S.filter==='practice'?m.practice:!m.practice)&&(S.filter!=='birthday'||m.birthday.slice(5,7)===month))&&(!S.query.trim()||m.name.includes(S.query.trim())||m.phone.includes(S.query.trim())));$('#member-table').innerHTML=data.length?`<div class="table-wrap"><table><thead><tr><th>会员 / 手机号</th><th>生日</th><th>身份证号码</th><th>储值余额</th><th>操作</th></tr></thead><tbody>${data.map(m=>`<tr><td>${esc(m.name||'未填写姓名')}<small>${esc(m.phone)}</small></td><td class="nowrap">${esc(m.birthday||'未填写')}</td><td>${esc(m.identity||'未填写')}</td><td class="money">${money(m.balance)}</td><td><div class="actions">${m.deleted_at?isAdmin()?`<button data-act="restore_member" data-id="${m.id}">恢复会员</button><button class="danger" data-act="purge" data-id="${m.id}">完全删除</button>`:'':`<button data-act="recharge" data-id="${m.id}">充值</button><button data-act="edit" data-id="${m.id}">编辑</button>${isAdmin()?`<button class="danger" data-act="archive" data-id="${m.id}">删除</button>`:''}`}<button data-act="history" data-id="${m.id}">流水</button></div></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><span class="empty-icon" aria-hidden="true">会</span><strong>${S.query.trim()?'未找到符合条件的会员':S.filter==='birthday'?'本月暂无生日会员':S.filter==='deleted'?'暂无已删除会员':'从第一位会员开始'}</strong><p>${S.query.trim()?'试试完整手机号，或检查姓名是否正确。':S.filter==='all'?'点击右上角“新增会员”，建立宾客档案。':'切换到“全部会员”可查看其他档案。'}</p></div>`;$$('[data-act]').forEach(b=>b.onclick=async()=>{const m=S.members.find(m=>m.id===b.dataset.id),a=b.dataset.act;try{if(a==='edit')memberDialog(m);else if(a==='history')await historyDialog(m);else if(a==='archive'||a==='purge')deleteDialog(m,a==='purge');else if(a==='restore_member'){await api('/api/action',{action:a,id:m.id});toast('会员已恢复');await load();}else transactionDialog(m,a);}catch(e){toast(e.message);}});}
function memberDialog(m){openModal(m?'编辑会员':'新增会员',`<form id="member-form" class="form">${m?.practice?'<div class="warning">此档案为历史练习数据</div>':''}<label class="field">姓名<input name="name" maxlength="50" value="${esc(m?.name||'')}"></label><label class="field">手机号 *<input name="phone" type="tel" required pattern="1[3-9][0-9]{9}" maxlength="11" value="${esc(m?.phone||'')}"></label><label class="field">生日<input name="birthday" inputmode="numeric" maxlength="10" placeholder="19910605" value="${esc(m?.birthday||'')}"><span class="muted">直接输入 8 位数字；身份证填写后可自动补全。</span></label><label class="field">身份证号码${m?'（留空保留）':''}<input name="identity" maxlength="18" placeholder="${esc(m?.identity||'')}"></label><button class="primary" type="submit">保存会员</button></form>`);bindForm('#member-form',async d=>{await api('/api/action',{action:m?'edit_member':'create_member',id:m?.id,...d});$('#modal').close();toast('会员资料已保存');await load();});}
function transactionDialog(m,kind){if(kind!=='recharge'){toast('储值消费请在百居易办理');return;}const sid=S.user.store_id||S.stores.find(s=>s.active)?.id||'';const eid='';const key=crypto.randomUUID();openModal(kind==='recharge'?'会员充值':'手动消费',`<p class="sub">${esc(m.name||'会员')} · ${esc(m.phone)} · 余额 ${money(m.balance)}</p><form id="transaction-form" class="form">${m.practice?'<div class="warning">练习操作，不发生真实收款、不计正式业绩</div>':''}<label class="field">金额（元）<input name="amount" inputmode="decimal" required autofocus placeholder="0.00"></label><div class="quick">${[100,200,500,1000].map(n=>`<button type="button" data-amount="${n}">¥${n}</button>`).join('')}</div><label class="field">${kind==='recharge'?'充值':'消费'}门店 *<select name="store_id" required>${storeOptions(sid)}</select></label>${kind==='recharge'?`<div class="field">业绩归属 *<div class="quick"><label class="radio"><input type="radio" name="attribution" value="staff" checked>员工</label><label class="radio"><input type="radio" name="attribution" value="walkin">上门客户</label></div></div><label class="field" id="employee-field">归属员工 *<select name="employee_id" required>${employeeOptions(sid,eid)}</select></label>`:''}${kind==='recharge'?`<label class="field">收款方式 *<select name="payment_method" required><option value="">请选择</option><option value="cash">现金</option><option value="wechat">微信</option><option value="alipay">支付宝</option><option value="bank">银行转账</option></select></label><label class="field">收款流水号（非现金必填）<input name="payment_reference" maxlength="100"></label><label class="radio"><input type="checkbox" name="receipt_confirmed" required>${m.practice?'已核对练习金额':'已核对实际到账金额（系统不会自动收款）'}</label>`:''}<label class="field">备注（选填）<input name="note" maxlength="200" placeholder="可填写房号或业务说明"></label><p class="muted">时间自动记录为提交时间（北京时间）。操作员：${esc(S.user.name)}。</p>${kind==='spend'?'<label class="radio"><input type="checkbox" required>已核对流水，本笔费用未扣款，也不会通过百居易重复扣款</label><div class="warning">百居易选择“储值消费”的收款由系统同步，请勿在此重复消费。短信尚未开通，本次消费不会发送短信。</div>':''}<button class="primary" type="submit">确认${kind==='recharge'?'充值':'消费'}</button></form>`);const form=$('#transaction-form');$$('[data-amount]').forEach(b=>b.onclick=()=>form.elements.amount.value=b.dataset.amount);if(kind==='recharge'){form.elements.store_id.onchange=()=>form.elements.employee_id.innerHTML=employeeOptions(form.elements.store_id.value,'');$$('input[name=attribution]').forEach(r=>r.onchange=()=>{const staff=form.elements.attribution.value==='staff';$('#employee-field').hidden=!staff;form.elements.employee_id.required=staff;});}bindForm('#transaction-form',async d=>{const r=await api('/api/action',{action:'transaction',id:m.id,kind,key,...d});$('#modal').close();toast(m.practice?'练习流水已保存，不计正式业绩':kind==='spend'?'消费已记账，短信未发送':'充值已记录，业绩归属已保存');await load();});}
const entryName=k=>({recharge:'充值',spend:'消费',recharge_refund:'充值退款',spend_refund:'消费退款',pms_spend:'百居易房费扣款',pms_refund:'百居易房费退回'})[k]||'历史流水';
async function historyDialog(m){const d=await api('/api/ledger?member='+encodeURIComponent(m.id));openModal('储值流水',`<p class="sub">${esc(m.name||'会员')} · ${esc(m.phone)}${m.practice?' · 练习数据':''}</p>${d.ledger.length?d.ledger.map(l=>`<article class="entry"><div class="row"><strong>${entryName(l.entry_type)}</strong><strong>${l.amount>0?'+':''}${money(l.amount)}</strong></div><p class="sub">${stamp(l.created)} · ${esc(l.store_name||'历史未归属')}</p><p class="sub">流水编号：${esc(l.id)}</p>${l.original_id?`<p class="sub">原流水：${esc(l.original_id)}</p>`:''}<p class="sub">业绩归属：${esc(l.employee_name||'不计员工充值业绩')}</p><p class="sub">操作员：${esc(l.operator_name)} · 余额 ${money(l.balance_after)}</p>${l.entry_type==='recharge'?`<p class="sub">收款：${esc(({cash:'现金',wechat:'微信',alipay:'支付宝',bank:'转账',legacy:'历史未记录'})[l.payment_method]||'未记录')} · ${esc(l.payment_reference||'无流水号')}</p>`:''}<p class="sub">${esc(l.note)}</p>${['spend','pms_spend'].includes(l.entry_type)?`<p class="sub">${m.practice?'练习数据，不发送短信':'短信未发送'}</p>`:''}${!m.deleted_at&&['recharge','spend'].includes(l.entry_type)&&(isAdmin()||l.store_id===S.user.store_id)?`<button data-refund="${esc(l.id)}">申请退款 / 纠错</button>`:''}</article>`).join(''):'<div class="empty">暂无流水</div>'}`);$$('[data-refund]').forEach(b=>b.onclick=()=>refundDialog(d.ledger.find(l=>l.id===b.dataset.refund),m));}
function refundDialog(l,m){const key=crypto.randomUUID();openModal('申请退款 / 纠错',`<p>${esc(m.name)} · 原${entryName(l.entry_type)} ${money(Math.abs(l.amount))}</p><p class="sub">${esc(l.id)}</p><form id="refund-form" class="form"><div class="warning">${['spend','pms_spend'].includes(l.entry_type)?'消费退款将返还会员储值余额。':'充值退款将扣减会员余额和原归属业绩，管理员需核对退还款项。'}申请经管理员审批后生效。原流水保留，改错请先退款再重新记账。</div><label class="field">退款金额（元）<input name="amount" required inputmode="decimal"></label><label class="field">退款 / 纠错原因<input name="reason" required maxlength="200"></label><button type="submit" class="primary">提交管理员审批</button></form>`);bindForm('#refund-form',async d=>{await api('/api/action',{action:'request_refund',original_id:l.id,key,...d});$('#modal').close();toast('申请已提交，可在“充值与业绩”查看审批状态');await load();});}
function deleteDialog(m,purge){const funded=m.balance!==0;openModal(purge?'完全删除会员':'删除会员',`<p class="sub">${esc(m.name||'会员')} · ${esc(m.phone)}</p><form id="delete-form" class="form"><div class="${purge?'danger-box':'warning'}">${funded?'该会员仍有余额，请先真实结清，不能直接删除。':purge?'将永久删除本机数据库中的会员资料、关联充值消费流水、通知记录及 PMS 映射，无法在系统中恢复。相关充值会从业绩统计中移除。云端旧版、手动导出和既有备份不受此操作影响。':'会员移入“已删除”，保留历史流水，可以恢复。'}</div>${purge?'<label class="field">会员手机号后四位<input name="phone_tail" required pattern="[0-9]{4}" maxlength="4" inputmode="numeric"></label><label class="field">输入“完全删除”<input name="confirmation" required autocomplete="off"></label>':''}<button type="submit" class="${purge?'danger primary':'primary'}" ${funded?'disabled':''}>${purge?'永久删除资料和关联流水':'确认删除'}</button></form>`);bindForm('#delete-form',async d=>{await api('/api/action',{action:purge?'purge_member':'archive_member',id:m.id,...d});$('#modal').close();toast(purge?'本机会员及关联流水已彻底删除':'会员已移至已删除列表');await load();});}
function performanceView(){const r=S.recharges;$('#view').innerHTML=`<div class="headline"><div><h1>充值与业绩</h1><p class="sub">按实际充值时间、门店和归属核算，按退款发生时间扣减充值退款；消费退款不计充值业绩。练习数据已排除。</p></div></div><section class="panel"><form id="report-filter" class="filters"><label class="field">开始日期<input type="date" name="start" value="${esc(S.filters.start||'')}"></label><label class="field">结束日期<input type="date" name="end" value="${esc(S.filters.end||'')}"></label><label class="field">门店<select name="store">${option('','全部可见门店',S.filters.store)}${S.stores.map(s=>option(s.id,s.name,S.filters.store)).join('')}</select></label><label class="field">业绩归属<select name="employee">${option('','全部归属',S.filters.employee)}${option('walkin','上门客户',S.filters.employee)}${S.employees.map(e=>option(e.id,e.name+' · '+(S.stores.find(s=>s.id===e.store_id)?.name||''),S.filters.employee)).join('')}</select></label><button class="primary" type="submit">查询</button></form><div class="summary"><div><p class="sub">净充值（充值－充值退款）</p><strong>${money(r.total)}</strong></div><div><p class="sub">充值 / 退款流水数</p><strong>${r.records.length}</strong></div></div><div class="table-wrap"><table><thead><tr><th>充值时间（北京时间）</th><th>会员 / 手机号</th><th>金额</th><th>充值门店</th><th>业绩归属</th><th>操作员</th></tr></thead><tbody>${r.records.map(l=>`<tr><td class="nowrap">${stamp(l.created)}<small>${entryName(l.entry_type)}</small></td><td>${esc(l.member_name||'会员')}<small>${esc(l.phone)}</small></td><td class="money">${money(l.amount)}</td><td>${esc(l.store_name||'历史未归属')}</td><td>${esc(l.employee_name||'历史未归属')}</td><td>${esc(l.operator_name)}</td></tr>`).join('')}</tbody></table>${!r.records.length?'<p class="empty">暂无符合条件的充值记录</p>':''}</div></section><section class="panel"><h2>业绩汇总</h2><div class="table-wrap"><table><thead><tr><th>门店</th><th>归属员工 / 上门客户</th><th>笔数</th><th>充值总额</th></tr></thead><tbody>${r.groups.map(g=>`<tr><td>${esc(g.store||'历史未归属')}</td><td>${esc(g.employee)}</td><td>${g.count}</td><td class="money">${money(g.amount)}</td></tr>`).join('')}</tbody></table></div><p class="sub">上门客户单独统计，不计入员工个人业绩。历史云端数据没有门店和员工信息的，显示为“历史未归属”。</p></section>`;$('#view').insertAdjacentHTML('beforeend',refundPanel());$$('[data-review]').forEach(b=>b.onclick=()=>reviewDialog(S.refunds.find(r=>r.id===b.dataset.review)));bindForm('#report-filter',async d=>{if(d.start&&d.end&&d.start>d.end)throw Error('开始日期不能晚于结束日期');const previous=S.filters;S.filters=d;try{await loadRecharges();}catch(e){S.filters=previous;throw e;}performanceView();});}
function settingsView(){
 const section=S.managementSection||'accounts',isBoss=isAdmin();
 const people=S.users.filter(u=>['staff','manager'].includes(u.role));const pending=people.filter(u=>u.status==='pending');
 const tabs=[['accounts','账号审批',pending.length],['employees','业绩归属员工',S.employees.filter(e=>e.active).length],['stores','门店',S.stores.length],['issues','储值待核对',S.auto?.counts?.blocked||0]];
 $('#view').innerHTML=`<div class="headline"><div><p class="eyebrow">TEAM MANAGEMENT</p><h1>${isBoss?'管理设置':'门店管理'}</h1><p class="sub">${isBoss?'管理团队、分配权限，让每笔业务有据可查。':'管理本店团队，及时跟进储值消费异常。'}</p></div><div class="management-heading-actions"><span class="tag">${isBoss?'管理员':esc(S.stores.find(x=>x.id===S.user.store_id)?.name||'本店')+' · 店长'}</span>${isBoss?'<button id="manager-settings" type="button">店长设置</button>':''}</div></div>
 <div class="management-navigation"><nav class="management-tabs" aria-label="管理分类">${tabs.map(([key,label,count])=>`<button data-management="${key}" class="${key===section?'active':''}">${label}<span>${count}</span></button>`).join('')}</nav>${isBoss?'<button id="integration-settings" type="button" class="quiet">系统连接设置 <span aria-hidden="true">→</span></button>':''}</div><section class="panel management-panel" id="management-content"></section>`;
 if(isBoss){$('#manager-settings').onclick=managerSettingsDialog;$('#integration-settings').onclick=async()=>{S.tab='pms';try{await load();}catch(e){toast(e.message);}};}
 const box=$('#management-content');
 if(section==='accounts'){
 const filter=S.accountFilter||(pending.length?'pending':'active');const filtered=people.filter(u=>filter==='all'||u.status===filter);
 box.innerHTML=`<div class="panel-heading"><div><h2>员工账号审批</h2><p class="sub">核实本人和百居易前厅身份后审批；门店与业绩名单将自动关联。</p></div></div><div class="segments account-filters">${[['pending','待审批'],['active','已启用'],['disabled','已停用'],['rejected','已拒绝'],['all','全部']].map(([k,t])=>`<button data-account-filter="${k}" class="${filter===k?'active':''}">${t}</button>`).join('')}</div><div class="team-list">${filtered.map(u=>`<article class="team-card"><div class="team-avatar">${esc(u.name.slice(0,1))}</div><div class="team-info"><strong>${esc(u.name)}</strong><p>${esc(u.username)}</p><small>${esc(S.stores.find(x=>x.id===u.store_id)?.name||'未选择门店 · 管理员分配')} · ${u.role==='manager'?'店长':'员工'}</small>${u.status==='rejected'?`<div class="rejection-note"><p>拒绝原因：${esc(u.rejection_reason||'未记录')}</p><small>${esc(u.rejected_by||'')} · ${stamp(u.rejected_at)}</small></div>`:''}</div><span class="status-pill ${u.status}">${({pending:'待审批',active:'已启用',disabled:'已停用',rejected:'已拒绝'})[u.status]}</span><div class="actions">${u.role==='staff'&&u.status!=='rejected'?`<button data-approve="${u.id}" class="${u.status==='pending'?'primary':''}">${u.status==='active'?'核对门店':'核实并审批'}</button>${u.status==='pending'?`<button data-reject="${u.id}" class="danger">拒绝申请</button>`:''}${u.status==='active'?`<button data-disable="${u.id}" class="danger">停用</button>`:''}`:''}</div></article>`).join('')||'<div class="empty"><strong>当前没有相关账号</strong><p>新员工提交注册申请后，会出现在待审批列表。</p></div>'}</div><p class="sub">${isBoss?'未选择门店的历史申请仅管理员可分配。':'仅显示本店申请；其他门店及未分配申请由管理员处理。'} 店长可审批本店普通员工；店长任免由管理员负责。</p>`;
 $$('[data-account-filter]').forEach(b=>b.onclick=()=>{S.accountFilter=b.dataset.accountFilter;settingsView();});
 }
 if(section==='employees')box.innerHTML=`<h2>业绩归属员工名单</h2><p class="sub">用于充值业绩归属，操作账号另行记录。审批员工时自动建立名单。</p><form id="employee-form" class="management-form"><label class="field">员工姓名<input name="name" required maxlength="50" placeholder="填写真实姓名"></label><label class="field">所属门店<select name="store_id" required>${storeOptions(isBoss?'':S.user.store_id)}</select></label><button class="primary" type="submit">添加员工</button></form><div class="team-list">${S.employees.map(e=>`<article class="team-card"><div class="team-avatar">${esc(e.name.slice(0,1))}</div><div class="team-info"><strong>${esc(e.name)}</strong><p>${esc(S.stores.find(x=>x.id===e.store_id)?.name||'')}</p>${people.some(u=>u.employee_id===e.id&&u.role==='manager'&&u.status==='active')?'<small>店长</small>':''}</div><span class="status-pill ${e.active?'active':'disabled'}">${e.active?'在职':'已停用'}</span>${isBoss||!people.some(u=>u.employee_id===e.id&&u.role==='manager')?`<button data-toggle="employee" data-id="${e.id}" data-active="${!e.active}">${e.active?'停用员工':'启用员工'}</button>`:''}</article>`).join('')||'<p class="sub">暂无员工，请先审批注册申请。</p>'}</div>`;
 if(section==='stores')box.innerHTML=`<h2>门店</h2><p class="sub">${isBoss?'维护营业门店，成员权限按所属门店分配。':'本店资料由管理员维护。'}</p>${isBoss?'<form id="store-form" class="management-form"><label class="field">门店名称<input name="name" placeholder="填写门店名称" required maxlength="50"></label><button type="submit" class="primary">添加门店</button></form>':''}<div class="store-grid">${S.stores.map(store=>`<article class="store-card"><span class="status-pill ${store.active?'active':'disabled'}">${store.active?'营业中':'已停用'}</span><h3>${esc(store.name)}</h3><p>${S.employees.filter(e=>e.store_id===store.id&&e.active).length} 位在职员工</p><small>店长：${esc(people.filter(u=>u.store_id===store.id&&u.role==='manager'&&u.status==='active').map(u=>u.name).join('、')||'待设置')}</small>${isBoss?`<button data-toggle="store" data-id="${store.id}" data-active="${!store.active}">${store.active?'停用门店':'启用门店'}</button>`:''}</article>`).join('')}</div>`;
 if(section==='issues'){box.innerHTML=`<div class="panel-heading"><div><h2>储值消费待核对</h2><p class="sub">查看订单的问题，处理后点击“刷新结果”。“填写备注”用于记录处理情况，不代表问题已解决。</p></div><button id="refresh-issues">刷新结果</button></div><div class="team-list">${issueCards()}</div>`;$('#refresh-issues').onclick=()=>load().catch(e=>toast(e.message));bindIssueReviews();}
 $$('[data-management]').forEach(b=>b.onclick=()=>{S.managementSection=b.dataset.management;settingsView();});
 if($('#store-form'))bindForm('#store-form',async d=>{await api('/api/action',{action:'add_store',...d});toast('门店已添加');await load();});
 if($('#employee-form'))bindForm('#employee-form',async d=>{await api('/api/action',{action:'add_employee',...d});toast('员工已添加');await load();});
 $$('[data-toggle]').forEach(b=>b.onclick=async()=>{try{await api('/api/action',{action:'toggle_'+b.dataset.toggle,id:b.dataset.id,active:b.dataset.active==='true'});await load();}catch(e){toast(e.message);}});
 $$('[data-approve]').forEach(b=>b.onclick=()=>approveDialog(S.users.find(u=>u.id===b.dataset.approve)));
 $$('[data-reject]').forEach(b=>b.onclick=()=>rejectApplicationDialog(S.users.find(u=>u.id===b.dataset.reject)));
 $$('[data-disable]').forEach(b=>b.onclick=async()=>{try{await api('/api/action',{action:'disable_user',id:b.dataset.disable});await load();}catch(e){toast(e.message);}});

}
function paymentGuide(){return `<section class="payment-guide" aria-label="储值消费操作说明"><div class="payment-guide-heading"><strong>百居易确认储值收款后，会员台自动扣余额</strong></div><p>填写会员手机号 → 房费收款选择“储值消费”并确认保存 → 在“消费同步记录”核对结果。</p><details><summary>未入住、入住中、已退房、取消，分别怎么记账？</summary><div class="table-wrap"><table><thead><tr><th>百居易中的操作或状态</th><th>会员台如何处理</th></tr></thead><tbody><tr><td>未入住 / 入住中 / 已退房</td><td>都按已确认的储值收款记账。只切换入住状态，不会再扣一遍，也不会退款。</td></tr><tr><td>仅创建订单、仅选会员来源或仅改房价</td><td>不会据此扣款。以订单收支中已确认的“储值消费”金额为准。</td></tr><tr><td>现金、微信、支付宝等付款</td><td>不扣会员卡；混合付款只同步储值消费部分。</td></tr><tr><td>整单已取消</td><td>核对取消后不再扣款；之前由系统自动扣过的余额会退回会员卡。</td></tr><tr><td>只取消部分房间 / 取消尚未同步</td><td>先查看记录与提示，交店长核对。不要把部分房间取消当作整单退款。</td></tr></tbody></table></div><p>手机号必须与会员档案一致，余额不足或同步异常时需处理后等待重试。充值在会员台办理，实际收款后才能记充值。</p><p>保存后同步需要时间，网络异常时会延迟。取消后确认记录显示“已取消 · 不扣款”，并查看流水中的退回记录；已取消订单的原扣款流水会保留，净扣款应为 0。历史手动扣费需另找店长核对。</p></details></section>`;}
function paymentRecordLabel(o){
 if(o.status==='cancelled')return o.charged===0?'已取消 · 不扣款':'取消待核对';
 return ({settled:'储值扣款已同步',external:'无已收储值款',blocked:'待核对',pending:'等待核对'})[o.status]||'等待核对';
}
function paymentRecordCards(){
 const orders=(S.auto?.orders||[]).filter(o=>o.status!=='historical');
 const query=(S.paymentQuery||'').trim(),filter=S.paymentFilter||'all';
 const shown=orders.filter(o=>(filter==='all'||o.status===filter)&&(!query||o.code.includes(query)||(o.member_name||'').includes(query)));
 $('#payment-record-list').innerHTML=shown.length?shown.map(o=>`<article class="payment-record"><div class="panel-heading"><strong>${esc(o.member_name||'会员待匹配')}</strong><span class="status-pill ${o.status==='blocked'?'pending':''}">${paymentRecordLabel(o)}</span></div><p class="sub">订单 ${esc(o.code)} · ${esc(S.stores.find(s=>s.id===o.store_id)?.name||'门店待确认')}</p><div class="payment-record-amount"><span>当前净扣款</span><strong>${Number.isSafeInteger(o.charged)?money(o.charged):'待核对'}</strong></div><p class="sub">${o.status==='cancelled'?'整单取消已同步，自动扣款净额应为 0。原扣款和退回流水保留。':o.status==='external'?'未确认储值收款；曾扣过的自动储值款按差额退回。':o.status==='blocked'?esc(o.reason||'请联系店长核对订单收支。'):o.status==='settled'?'已按储值收款同步。只切换未入住、入住中、已退房，不会重复扣款。':'尚未核对完成，请稍后刷新结果。'}</p><p class="sub">最近核对：${stamp(o.checked)}</p></article>`).join(''):'<div class="empty"><strong>暂无符合条件的同步记录</strong><p>新收款可能尚在等待扫描，请稍后刷新。没有记录不代表已扣款。</p></div>';
 $$('[data-payment-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.paymentFilter===(S.paymentFilter||'all'));b.setAttribute('aria-pressed',String(b.dataset.paymentFilter===(S.paymentFilter||'all')));});
}
function showPaymentRecords(){
 openModal('消费同步记录',`<p class="sub">查看百居易储值收款对应的余额结果。以下净扣款已抵减自动退回金额，不含历史手动消费。</p>${S.auto?.error?'<p class="warning">'+esc(S.auto.error)+'</p>':''}${!S.auto?.enabled?'<p class="warning">自动同步已暂停，当前显示上次核对结果。请联系管理员。</p>':''}<div class="payment-record-toolbar"><div class="segments">${[['all','全部'],['blocked','待核对'],['cancelled','已取消']].map(([k,n])=>`<button data-payment-filter="${k}">${n}</button>`).join('')}</div><button id="refresh-payment-records" class="quiet">刷新结果</button></div><input id="payment-record-search" type="search" aria-label="查找消费同步记录" placeholder="输入订单号或会员姓名" value="${esc(S.paymentQuery||'')}"><div id="payment-record-list"></div><p class="sub">显示当前账号可见的最近 100 条记录，异常优先。更多交易请到会员流水核对。</p>`);
 $('#modal-body').oninput=null;
 $('#payment-record-search').oninput=e=>{S.paymentQuery=e.target.value;paymentRecordCards();};
 $$('[data-payment-filter]').forEach(b=>b.onclick=()=>{S.paymentFilter=b.dataset.paymentFilter;paymentRecordCards();});
 $('#refresh-payment-records').onclick=async e=>{const b=e.currentTarget;b.disabled=true;try{const [a,m]=await Promise.all([api('/api/member-orders'),api('/api/members')]);S.auto=a;S.members=m.members;render();showPaymentRecords();}catch(err){toast(err.message);b.disabled=false;}};
 paymentRecordCards();
}
function issueGuidance(o){
 const reason=o.reason||'';
 if(/连接失败|正在变化|同步|暂未找到/.test(reason))return ['员工：等待同步恢复，再刷新记录；若已在百居易整单取消，确认取消已保存后告知店长。','店长：确认取消退回结果和原自动扣款流水。网络异常时暂不调整余额，不要重复退款；持续异常联系管理员。'];
 if(reason.includes('余额不足'))return ['员工：核实客人是否充值，实际收到钱后再办理充值。补足后，系统会自动重试扣款。','客人晚点付款：告知店长跟进；不要提前记充值或再次手动消费。若改用现金、微信等付款，请在百居易按实际收款方式处理。'];
 if(/手机|电话/.test(reason))return ['员工：到百居易核对并保存会员本人的手机号，再等待同步。','补填前先查看会员流水；若这笔房费已经手动扣过，请先找店长核对，避免再次自动扣款。'];
 return ['员工：按上方原因核对百居易订单和收支，不确定时交给店长。','店长：核对订单与会员流水；涉及重复扣款，核实后提交退款／纠错申请，由管理员审核。'];
}
function issueCards(){return (S.auto?.orders||[]).filter(o=>o.status==='blocked').map(o=>`<article class="issue-card"><div class="panel-heading"><strong>${esc(o.member_name||'会员待匹配')}</strong><span class="status-pill pending">待处理</span></div><p class="sub">订单 ${esc(o.code)} · ${esc(S.stores.find(s=>s.id===o.store_id)?.name||'门店待确认')}</p><p><strong>${esc(o.reason||'请核对订单与收支')}</strong></p><p class="sub">本订单同步金额：应扣 ${Number.isSafeInteger(o.target)?money(o.target):'待核对'} · 当前净扣 ${Number.isSafeInteger(o.charged)?money(o.charged):'待核对'}<br>不含手动消费。当前余额请到会员档案核对。</p><ol>${issueGuidance(o).map(t=>`<li>${esc(t)}</li>`).join('')}</ol><p class="sub">核对时间：${stamp(o.checked)}。处理后刷新结果，确认流水再向客人说明。</p>${o.review_note?`<div class="review-note">处理备注：${esc(o.review_note)}<small>${esc(o.reviewer)} · ${stamp(o.reviewed_at)}</small></div>`:''}<div class="actions"><button data-find-member>查找会员与流水</button>${canManage()?`<button data-review-order="${esc(o.code)}">填写备注</button>`:''}</div></article>`).join('')||'<div class="empty"><strong>暂无待核对订单</strong><p>同步发现异常时会在这里提醒。</p></div>';}
function bindIssueReviews(){ $$('[data-find-member]').forEach(b=>b.onclick=()=>{$('#modal').close();S.tab='members';S.filter='all';S.query='';render();$('#search').focus();toast('请用会员本人手机号查找，再查看流水。');}); $$('[data-review-order]').forEach(b=>b.onclick=()=>{const code=b.dataset.reviewOrder;openModal('填写处理备注',`<p class="sub">订单 ${esc(code)}</p><p class="sub">订单信息请到百居易修改。这里填写你做了什么，或还有什么问题，方便同事继续处理。</p><form id="review-order-form" class="form"><label class="field">处理备注<textarea name="note" required maxlength="500" rows="4" placeholder="例如：已在百居易补填手机号，等待系统重新检查。"></textarea></label><p class="sub">保存备注不会扣款或退款。订单是否处理成功，请查看后续同步结果。</p><button class="primary" type="submit">保存备注</button></form>`);bindForm('#review-order-form',async d=>{await api('/api/action',{action:'review_member_order',code,note:d.note});$('#modal').close();toast('备注已保存，订单仍需等待系统核对');await load();});});}
function rejectApplicationDialog(u){
 if(!u||u.status!=='pending')return;
 openModal('拒绝员工申请',`<p class="sub">${esc(u.name)} · ${esc(u.username)}</p><form id="reject-application-form" class="form"><p>拒绝后，该账号不能登录。申请、原因及处理人会保留在“已拒绝”中。</p><label class="field">拒绝原因<textarea name="reason" required maxlength="500" rows="3" placeholder="例如：重复注册，请使用原已启用账号。"></textarea></label><button type="submit" class="danger primary">确认拒绝</button></form>`);
 bindForm('#reject-application-form',async d=>{await api('/api/action',{action:'reject_user',id:u.id,reason:d.reason});$('#modal').close();S.accountFilter='rejected';await load();toast('申请已拒绝，处理记录已保存');});
}
async function approveAtStore(u,storeId,verified){await api('/api/action',{action:'approve_user',id:u.id,store_id:storeId,frontdesk_verified:verified===true});}
function approveDialog(u){
 const hasStores=S.stores.some(s=>s.active);
 openModal('核实前厅身份并审批',`<p class="sub">${esc(u.name)} · ${esc(u.username)}</p><form id="approve-form" class="form"><label class="field">所属门店 *<select name="store_id" required>${storeOptions(u.store_id||'')}</select></label><p class="sub">选择该员工所属门店，系统会自动关联或建立同名员工的业绩归属记录，无需事先重复添加。</p><label class="radio"><input type="checkbox" name="frontdesk_verified" required>我已核实此人为该账号本人，并在百居易“团队与权限”中具有前厅角色</label><p class="sub">审批后，该账号只能办理所选门店的充值消费。调整门店不会改变历史充值记录。</p>${hasStores?'':'<p class="error">请先添加并启用门店。</p>'}<button type="submit" class="primary" ${hasStores?'':'disabled'}>确认审批</button></form>`);
 bindForm('#approve-form',async d=>{await approveAtStore(u,d.store_id,d.frontdesk_verified==='on');$('#modal').close();toast('账号已启用，所属门店已保存');await load();});
}

function passwordDialog(){openModal('修改密码',`<form id="password-form" class="form"><label class="field">原密码<input name="old_password" required type="password" autocomplete="current-password"></label><label class="field">新密码<input name="new_password" type="password" required minlength="10" maxlength="128" autocomplete="new-password"></label><button type="submit" class="primary">修改并重新登录</button></form>`);bindForm('#password-form',async d=>{await api('/api/action',{action:'change_password',...d});$('#modal').close();toast('密码已修改，请重新登录');await boot();});}
$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeModal();});
boot();

function refundPanel(){return `<section class="panel"><h2>退款与纠错审批</h2><p class="sub">此列表显示${isAdmin()?'全部门店':'所属门店'}的申请，不受上方业绩筛选影响。</p>${(S.refunds||[]).map(r=>`<article class="entry"><strong>${esc(r.member_name)} · ${entryName(r.entry_type)}退款 ${money(r.amount)} ${r.practice?'（练习）':''}</strong><p class="sub">${esc(r.store_name)} · ${esc(r.requester_name)} · ${stamp(r.created)}</p><p>${esc(r.reason)}</p><p>状态：${({pending:'待管理员审批',approved:'已同意并记账',rejected:'已拒绝'})[r.status]}${r.reviewer?' · 审批人：'+esc(r.reviewer):''}</p>${isAdmin()&&r.status==='pending'?`<button data-review="${r.id}">处理申请</button>`:''}</article>`).join('')||'<p>暂无退款申请</p>'}</section>`;}
function reviewDialog(r){openModal('处理退款申请',`<p>${esc(r.member_name)} · ${money(r.amount)} · ${esc(r.reason)}</p><form id="review-form" class="form"><label class="field">审批结果<select name="decision"><option value="rejected">拒绝申请（不改余额）</option><option value="approved">同意退款并记账</option></select></label>${r.entry_type==='recharge'?`<label class="radio"><input type="checkbox" name="refund_confirmed">${r.practice?'已核对练习退款':'已核对退还客户款项（系统不会自动转账）'}</label>`:'<p class="sub">同意后返还储值余额，不增加充值业绩。</p>'}<button type="submit" class="primary">确认处理</button></form>`);bindForm('#review-form',async d=>{await api('/api/action',{action:'review_refund',id:r.id,...d});$('#modal').close();await load();toast('退款申请已处理');});}
function forgotDialog(){const ready=S.recovery?.available===true;if(!ready){openModal('忘记密码', '<p class="sub">请联系门店管理员协助处理账号登录问题。</p><p class="sub">短信找回尚未开通，当前无法通过验证码重设密码。请勿将密码发送到工作群。</p>');return;}openModal('短信验证码找回密码',`<p class="sub">使用注册账号的手机号接收验证码，验证通过后设置新密码。</p>${!ready?'<div class="warning" role="status">短信验证码服务尚未开通，暂时无法发送验证码或找回密码。请使用原密码登录。</div>':''}<form id="forgot-form" class="form"><label class="field">登录手机号<input name="username" type="tel" required pattern="1[3-9][0-9]{9}" maxlength="11" autocomplete="username" placeholder="注册账号使用的手机号"></label><button type="button" id="send-reset-code" ${ready?'':'disabled'}>获取短信验证码</button><label class="field">短信验证码<input name="code" required inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" ${ready?'':'disabled'}></label><label class="field">新密码<input name="new_password" type="password" required minlength="10" maxlength="128" autocomplete="new-password" ${ready?'':'disabled'}></label><button type="submit" class="primary" ${ready?'':'disabled'}>验证并重设密码</button></form>`);$('#send-reset-code').onclick=async()=>{const form=$('#forgot-form'),button=$('#send-reset-code');if(!form.elements.username.reportValidity())return;button.disabled=true;try{const r=await api('/api/password/send-code',{username:form.elements.username.value});toast(r.message);}catch(e){formError(form,e);}finally{button.disabled=!ready;}};bindForm('#forgot-form',async d=>{const r=await api('/api/password/verify-code',d);$('#modal').close();S.authMessage=r.message;authView();});}

function autoPanel(){const p={...(S.auto||{}),orders:(S.auto?.orders||[]).filter(o=>o.status!=='historical')};const labels={blocked:'待处理',pending:'等待核对',settled:'储值已同步',cancelled:'已取消 · 不扣款',historical:'历史订单不扣款',external:'无已收储值款 / 已转线下'};return `<section class="panel"><h2>百居易储值消费同步 · ${p.enabled?'已启用':'已暂停'}</h2><p>在百居易订单收支中，将房费收款方式选为<strong>储值消费</strong>，保存会员手机号，并确认收款记录。会员台按实际储值支付金额扣款。</p><p class="sub">现金、微信等线下付款不扣会员卡。订单来源不作为扣款依据；消费门店按房间分组核对。当前不自动同步充值，充值继续在会员台记录。</p>${p.error?`<p class="warning">${esc(p.error)}</p>`:''}<p>最近扫描：${stamp(p.last_scan)} · 待处理：${p.counts?.blocked||0} 单</p><button id="auto-refresh">刷新同步结果和会员余额</button>${isAdmin()&&(!S.remote||p.enabled)?` <button id="auto-control">${p.enabled?'暂停自动同步':'恢复储值消费同步'}</button>`:''}${isAdmin()&&S.remote&&!p.enabled?'<p class="sub">恢复同步请到主机本机入口操作。</p>':''}<div class="table-wrap"><table><thead><tr><th>订单</th><th>会员</th><th>应扣储值</th><th>净扣储值</th><th>状态 / 原因</th><th>核对时间</th></tr></thead><tbody>${(p.orders||[]).map(o=>`<tr><td>${esc(o.code)}</td><td>${esc(o.member_name||'待匹配')}</td><td>${o.target==null?'待核对':money(o.target)}</td><td>${money(o.charged)}</td><td>${labels[o.status]||esc(o.status)}${o.reason?`<small>${esc(o.reason)}</small>`:''}</td><td>${stamp(o.checked)}</td></tr>`).join('')}</tbody></table></div>${p.orders?.length?'':'<p class="empty">暂无储值消费记录</p>'}<details><summary>同步与异常处理说明</summary><p class="sub">仅处理 ${stamp(p.started)} 后创建的订单。每轮完成后约 30 秒再次核对，网络或记录量可能延长等待。主机需保持运行。手机号缺失、余额不足、分组不明确时不扣款，修正后重试。请勿对同一订单再次手动消费。</p><p class="sub">调整已收储值记录的金额后，按差额调整余额；仅修改房价不会改变实际储值支付金额。整单取消退回已扣储值。原收款记录被删除或移到其他订单时暂停核对，不猜测退款。独立支出退款尚未自动接入。</p><p class="sub">收款查询按操作日期覆盖首次启用前一天起的记录；更早回填的收款需另行核对。只读接入不会回写百居易，短信未开通。显示最近 100 单，异常优先。</p></details></section>`;}

function bindAuto(){if($('#auto-refresh'))$('#auto-refresh').onclick=async()=>{try{await load();}catch(e){toast(e.message);}};if($('#auto-control'))$('#auto-control').onclick=async e=>{const enabled=S.auto?.enabled;if(!confirm(enabled?'暂停后，储值收款及取消暂不调整余额。确认暂停？':'恢复后按已确认的储值收款及会员手机号同步余额，处理暂停期间的变化。确认恢复？'))return;e.target.disabled=true;try{await api('/api/pms/'+(enabled?'pause':'enable'),{});await load();toast(enabled?'自动记账已暂停':'自动记账已启用，等待下一轮核对');}catch(err){toast(err.message);e.target.disabled=false;}};}
function pmsView(){const p=S.pms;$('#view').innerHTML=`<div class="headline"><div><h1>百居易会员对接</h1><p class="sub">员工在百居易订单收支选择“储值消费”，会员台同步余额。</p></div></div>${autoPanel()}<section class="panel"><h2>只读账号授权</h2><p>${p.configured?'只读授权已保存':'尚未保存只读授权'}</p>${S.auto?.started?'<p>授权已用于自动记账，更换账号请联系维护人员核对历史订单。</p>':S.remote?'<p>请在主机的本机入口保存授权。</p>':`<form id="pms-config" class="form"><label class="field">百居易只读 Access Token<input name="token" type="password" required minlength="8" maxlength="4096" autocomplete="off"></label><button class="primary" type="submit">保存只读授权</button></form>${p.configured?'<button id="pms-remove" class="danger">移除本机授权</button>':''}`}</section>`;bindAuto();if($('#pms-config'))bindForm('#pms-config',async(d,f)=>{await api('/api/pms/configure',d);f.elements.token.value='';await load();});if($('#pms-remove'))$('#pms-remove').onclick=async()=>{if(!confirm('移除本机保存的百居易授权？'))return;try{await api('/api/pms/disconnect',{});await load();}catch(e){toast(e.message);}};}

let autoRefreshing=false;
setInterval(async()=>{if(autoRefreshing||!S.user||document.hidden||$('#modal')?.open||$('.account-menu')?.open||$('.payment-guide details')?.open||S.saving||!['members','pms'].includes(S.tab)||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;autoRefreshing=true;try{await load();}catch(e){/* Keep the last verified balances; the connection status updates on manual refresh. */}finally{autoRefreshing=false;}},30000);

function managerSettingsDialog(){
 if(!isAdmin())return;
 openModal('店长设置',`<form id="manager-form" class="form"><label class="field">门店<select name="store_id" required>${storeOptions('')}</select></label><label class="field">员工<select name="user_id" required disabled><option value="">先选择门店</option></select></label><p id="manager-summary" class="sub">选择门店和员工后设置权限。</p><button id="manager-save" type="submit" class="primary" disabled>选择员工</button></form>`);
 const form=$('#manager-form'),select=form.elements.user_id,button=$('#manager-save');
 const candidates=()=>S.users.filter(u=>u.store_id===form.elements.store_id.value&&u.status==='active'&&['staff','manager'].includes(u.role)&&S.employees.some(e=>e.id===u.employee_id&&e.store_id===u.store_id&&e.active));
 function selection(){
  const user=candidates().find(u=>u.id===select.value);button.disabled=!user;
  button.textContent=user?(user.role==='manager'?'停用店长':'设为店长'):'选择员工';
  $('#manager-summary').textContent=user?(user.role==='manager'?'当前为店长。停用店长权限后，仍可作为普通员工登录。':'设置后可审批本店员工、维护本店名单并跟进储值异常。'):'只列出本店已审批、已启用的员工账号。';
 }
 form.elements.store_id.onchange=()=>{const users=candidates();select.innerHTML=option('',users.length?'选择员工':'暂无可设置的员工','')+users.map(u=>option(u.id,u.name+(u.role==='manager'?' · 店长':''),'')).join('');select.disabled=!users.length;selection();};
 select.onchange=selection;
 bindForm('#manager-form',async d=>{const user=candidates().find(u=>u.id===d.user_id);if(!user)throw Error('请先选择有效员工');const role=user.role==='manager'?'staff':'manager';await api('/api/action',{action:'set_manager_role',id:user.id,role});$('#modal').close();await load();toast(role==='manager'?'已设为店长':'已停用店长权限，保留普通员工账号');});
}


'use strict';
