authView=function(){v1BaseAuth();if($('#forgot'))$('#forgot').textContent='登录遇到问题';};

rechargeRanking=function(){
 const board=S.ranking||{},leaders=board.leaders||[],labels=['冠军','亚军','季军'];
 const expanded=S.rankingOpen??matchMedia('(min-width:761px)').matches;
 const entries=Array.from({length:3},(_,i)=>leaders[i]||{rank:i+1});
 return `<details class="recharge-ranking ranking-v1" ${expanded?'open':''}><summary><strong>本月充值榜</strong><span>${esc(board.period?Number(board.period.slice(5))+'月 · 全门店':'全门店')}</span><b aria-hidden="true">⌄</b></summary><div class="ranking-body">${board.unavailable?'<p class="ranking-empty">暂未更新，请稍后刷新。</p>':`<ol class="ranking-list">${entries.map(p=>`<li><span class="ranking-medal rank-${p.rank}">${leaders.filter(q=>q.rank===p.rank).length>1?'并列':''}${labels[p.rank-1]}</span><div class="ranking-person"><strong>${esc(p.employee||'虚位以待')}</strong><small title="${esc(p.store||'')}">${esc(p.store||'期待你的成绩')}</small></div><span class="ranking-amount">${p.employee?money(p.amount):'—'}</span></li>`).join('')}</ol>`}<p class="ranking-help" title="北京时间自然月净充值；已完成的充值退款按发生时间扣减，上门客户及练习记录不参榜。同额并列，最多显示3人。">本月净充值，已扣充值退款</p></div></details>`;
};

render=function(){
 const active=S.members.filter(m=>!m.deleted_at&&!m.practice),month=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Shanghai',month:'2-digit'});
 if((S.tab==='settings'&&!canManage())||(S.tab==='pms'&&!isAdmin()))S.tab='members';
 if(S.filter==='practice'||(!isAdmin()&&S.filter==='deleted'))S.filter='all';
 $('#app').innerHTML=`<main class="shell v1-shell"><div class="workspace-top"><header class="mast"><div class="brand"><b>会</b><div>会员台<small>Best Dream</small></div></div><details class="account-menu"><summary>我的账户 <span aria-hidden="true">⌄</span></summary><div class="account-card"><strong>${esc(S.user.name)}</strong><p>${esc(S.stores.find(s=>s.id===S.user.store_id)?.name||'未分配门店')}</p><small>${isAdmin()?'管理员':S.user.role==='manager'?'店长':'前厅员工'}</small><div class="account-actions"><button id="password">修改密码</button><button id="logout">退出登录</button></div></div></details></header><nav class="nav" aria-label="工作导航">${[['members','会员档案'],['performance','充值与业绩'],...(canManage()?[['settings',isAdmin()?'管理设置':'门店管理']]:[])].map(([k,n])=>`<button data-tab="${k}" class="${S.tab===k||k==='settings'&&S.tab==='pms'?'active':''}" aria-current="${S.tab===k?'page':'false'}">${n}</button>`).join('')}</nav>${rechargeRanking()}</div><div id="view"></div><footer class="foot app-footer"><span>Best Dream · 酒店会员服务</span><span>每笔收支，清晰记录</span></footer></main>`;
 $$('[data-tab]').forEach(b=>b.onclick=async()=>{S.tab=b.dataset.tab;try{await load();}catch(e){toast(e.message);}});
 $('#logout').onclick=async()=>{await api('/api/logout',{});await boot();};$('#password').onclick=passwordDialog;
 const ranking=$('.ranking-v1');ranking.ontoggle=()=>{S.rankingOpen=ranking.open;};
 if(S.tab==='members'){
  const birthdays=active.filter(m=>m.birthday.slice(5,7)===month).length;
  $('#view').innerHTML=`<div class="headline"><div><h1>会员管理</h1><p class="sub">充值在会员台，房费储值消费在百居易。</p></div><button id="new-member" class="primary">＋ 新增会员</button></div><section class="member-panel"><div class="toolbar member-searchbar"><label class="member-search"><span>查找会员</span><input id="search" type="search" placeholder="输入姓名或手机号" aria-label="搜索会员" value="${esc(S.query)}"></label><div class="segments">${[['all',`全部会员 ${active.length}`],['birthday',`本月生日 ${birthdays}`],...(isAdmin()?[['deleted','已删除']]:[])].map(([k,n])=>`<button data-filter="${k}" aria-pressed="${S.filter===k}" class="${S.filter===k?'active':''}">${n}</button>`).join('')}</div></div><div class="workspace-overview"><section class="balance-overview" aria-label="会员储值余额"><span>会员储值余额</span><strong>${money(active.reduce((s,m)=>s+m.balance,0))}</strong></section><div class="member-heading-actions"><button id="payment-records">消费同步记录</button><button id="auto-refresh" class="quiet" aria-label="刷新同步结果和会员余额">刷新余额</button></div></div>${memberNotice()}${paymentGuide()}<div id="member-table"></div></section>`;
  $('#new-member').onclick=()=>memberDialog();$('#search').oninput=e=>{S.query=e.target.value;memberTable();};
  $$('[data-filter]').forEach(b=>b.onclick=()=>{S.filter=b.dataset.filter;render();});memberTable();bindAuto();
  $('#payment-records').onclick=showPaymentRecords;if($('#show-issues'))$('#show-issues').onclick=showMemberIssues;
 }
 if(S.tab==='performance')performanceView();if(S.tab==='settings')settingsView();
 if(S.tab==='pms'){pmsView();$('#view').insertAdjacentHTML('afterbegin','<button id="back-settings" class="quiet">← 返回管理设置</button>');$('#back-settings').onclick=async()=>{S.tab='settings';try{await load();}catch(e){toast(e.message);}};}
};

paymentGuide=function(){
 const holder=document.createElement('div');holder.innerHTML=v1BaseGuide();
 const section=holder.firstElementChild,details=section.querySelector('details');
 const introduction=section.querySelector(':scope > p');
 details.querySelector('summary').textContent='消费记账说明：百居易确认储值收款后，自动扣会员余额';
 if(introduction)details.querySelector('summary').after(introduction);
 section.replaceChildren(details);return section.outerHTML;
};

function v1Actions(m){return `${m.deleted_at?isAdmin()?`<button data-act="restore_member" data-id="${m.id}">恢复会员</button><button data-act="purge" data-id="${m.id}" class="danger">完全删除</button>`:'':`<button data-act="recharge" data-id="${m.id}" class="primary">充值</button>`}<button data-act="history" data-id="${m.id}">流水</button>`;}
memberTable=function(){
 const month=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Shanghai',month:'2-digit'});
 const data=S.members.filter(m=>(S.filter==='deleted'?m.deleted_at:!m.deleted_at&&!m.practice&&(S.filter!=='birthday'||m.birthday.slice(5,7)===month))&&(!S.query.trim()||m.name.includes(S.query.trim())||m.phone.includes(S.query.trim())));
 $('#member-table').innerHTML=data.length?`<div class="table-wrap member-desktop"><table><thead><tr><th>会员 / 手机号</th><th>储值余额</th><th>生日</th><th>操作</th></tr></thead><tbody>${data.map(m=>`<tr><td><button class="member-name" data-act="details" data-id="${m.id}" aria-label="查看${esc(m.name||'会员')}详情">${esc(m.name||'未填写姓名')}</button><small>${esc(m.phone)}</small></td><td class="money">${money(m.balance)}</td><td>${esc(m.birthday||'未填写')}</td><td><div class="actions">${v1Actions(m)}</div></td></tr>`).join('')}</tbody></table></div><div class="member-mobile">${data.map(m=>`<article class="member-card"><div class="member-card-main"><div><button class="member-name" data-act="details" data-id="${m.id}" aria-label="查看${esc(m.name||'会员')}详情">${esc(m.name||'未填写姓名')}</button><p>${esc(m.phone)}</p></div><div class="member-card-balance"><small>储值余额</small><strong>${money(m.balance)}</strong></div></div><div class="member-card-footer"><button class="quiet" data-act="details" data-id="${m.id}">查看详情 →</button><div class="actions">${v1Actions(m)}</div></div></article>`).join('')}</div>`:`<div class="empty"><strong>${S.query.trim()?'未找到符合条件的会员':S.filter==='birthday'?'本月暂无生日会员':S.filter==='deleted'?'暂无已删除会员':'从第一位会员开始'}</strong><p>${S.query.trim()?'试试完整手机号，或检查姓名是否正确。':'切换筛选，或点击“新增会员”建立档案。'}</p></div>`;
 $$('[data-act]').forEach(b=>b.onclick=async()=>{
  const m=S.members.find(m=>m.id===b.dataset.id),a=b.dataset.act;
  try{if(a==='details')v1MemberDetails(m);else if(a==='edit')memberDialog(m);else if(a==='history')await historyDialog(m);else if(a==='archive'||a==='purge')deleteDialog(m,a==='purge');else if(a==='restore_member'){await api('/api/action',{action:a,id:m.id});toast('会员已恢复');await load();}else transactionDialog(m,a);}catch(e){toast(e.message);}
 });
};
function v1MemberDetails(m){
 openModal('会员详情',`<div class="member-detail-identity"><strong>${esc(m.name||'未填写姓名')}</strong><p>${esc(m.phone)}</p><span>${m.deleted_at?'已删除会员':'有效会员'}</span></div><dl class="member-detail-grid"><div><dt>储值余额</dt><dd>${money(m.balance)}</dd></div><div><dt>生日</dt><dd>${esc(m.birthday||'未填写')}</dd></div><div><dt>身份证号码</dt><dd>${esc(m.identity||'未填写')}</dd></div></dl><div class="member-detail-actions">${!m.deleted_at?'<button id="detail-edit">编辑资料</button>':''}${isAdmin()&&!m.deleted_at?'<button id="detail-archive" class="danger">删除会员</button>':''}</div>`);
 if($('#detail-edit'))$('#detail-edit').onclick=()=>memberDialog(m);if($('#detail-archive'))$('#detail-archive').onclick=()=>deleteDialog(m,false);
}

transactionDialog=function(m,kind){
 if(kind!=='recharge'){toast('储值消费请在百居易办理');return;}
 const sid=S.user.store_id||S.stores.find(s=>s.active)?.id||'',key=crypto.randomUUID();
 openModal('会员充值',`<div class="recharge-member"><strong>${esc(m.name||'会员')}</strong><span>${esc(m.phone)}</span><small>当前余额 ${money(m.balance)}</small></div><form id="transaction-form" class="form recharge-form">${m.practice?'<p class="warning">练习操作，不发生真实收款，不计正式业绩。</p>':''}<fieldset><legend>充值金额</legend><label class="field">金额（元）<input name="amount" inputmode="decimal" required autofocus placeholder="0.00" autocomplete="off"></label><div class="quick">${[100,200,500,1000].map(n=>`<button type="button" data-amount="${n}">¥${n}</button>`).join('')}</div></fieldset><fieldset><legend>收款信息</legend><label class="field">收款方式 *<select name="payment_method" required><option value="">请选择实际收款方式</option><option value="cash">现金</option><option value="wechat">微信</option><option value="alipay">支付宝</option><option value="bank">银行转账</option></select></label><label class="field" id="payment-reference-field" hidden>收款流水号 *<input name="payment_reference" maxlength="100" placeholder="填写实际到账的收款流水号"></label><label class="receipt-check"><input type="checkbox" name="receipt_confirmed" required><span>${m.practice?'已核对练习金额':'已确认钱款实际到账'}<small>会员台只记账，不会向客人收款。</small></span></label></fieldset><fieldset><legend>门店与业绩归属</legend><label class="field">充值门店 *<select name="store_id" required>${storeOptions(sid)}</select></label><div class="field">业绩归属 *<div class="quick"><label class="radio"><input type="radio" name="attribution" value="staff" checked>员工</label><label class="radio"><input type="radio" name="attribution" value="walkin">上门客户</label></div></div><label class="field" id="employee-field">归属员工 *<select name="employee_id" required>${employeeOptions(sid,'')}</select></label></fieldset><details class="recharge-note"><summary>添加备注（选填）</summary><label class="field">备注<input name="note" maxlength="200" placeholder="可填写业务说明"></label></details><p class="muted">操作员：${esc(S.user.name)} · 提交时间自动记录</p><div class="recharge-submit"><button class="primary" type="submit">确认记录充值</button></div></form>`);
 const form=$('#transaction-form');
 $$('[data-amount]').forEach(b=>b.onclick=()=>{form.elements.amount.value=b.dataset.amount;S.dirty=true;form.elements.amount.focus();});
 form.elements.store_id.onchange=()=>form.elements.employee_id.innerHTML=employeeOptions(form.elements.store_id.value,'');
 form.elements.payment_method.onchange=()=>{const required=['wechat','alipay','bank'].includes(form.elements.payment_method.value);$('#payment-reference-field').hidden=!required;form.elements.payment_reference.required=required;if(!required)form.elements.payment_reference.value='';};
 $$('input[name=attribution]').forEach(r=>r.onchange=()=>{const staff=form.elements.attribution.value==='staff';$('#employee-field').hidden=!staff;form.elements.employee_id.required=staff;});
 bindForm('#transaction-form',async d=>{await api('/api/action',{action:'transaction',id:m.id,kind,key,...d});$('#modal').close();toast(m.practice?'练习流水已保存，不计正式业绩':'充值已记录，业绩归属已保存');await load();});
};

issueCards=function(){
 const holder=document.createElement('div');holder.innerHTML=v1BaseIssueCards();
 holder.querySelectorAll('.issue-card').forEach(card=>{
  const steps=card.querySelector('ol');if(!steps)return;
  const paragraphs=Array.from(card.children).filter(e=>e.tagName==='P');
  const reason=paragraphs[1]?.textContent||'';
  const next=document.createElement('p');next.className='issue-next';
  next.textContent=reason.includes('连接失败')?'下一步：等待连接恢复后刷新核对；请勿重复扣费或退款。':steps.querySelector('li')?.textContent||'请联系店长核对订单与流水。';
  steps.before(next);
  const details=document.createElement('details');details.className='issue-responsibilities';
  const summary=document.createElement('summary');summary.textContent='查看员工与店长处理说明';details.append(summary);steps.before(details);details.append(steps);
 });return holder.innerHTML;
};


