function v2MembersView(){
 const active=S.members.filter(m=>!m.deleted_at&&!m.practice),month=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Shanghai',month:'2-digit'});
 const birthdays=active.filter(m=>m.birthday.slice(5,7)===month).length;
 $('#view').innerHTML=`<section class="overview-v2"><div class="welcome-v2"><span class="overline-v2">MEMBER DESK</span><h1>会员管理<span class="headline-spark" aria-hidden="true">${v2Icon('spark')}</span></h1><p>查找会员、办理充值，让每一次服务清楚而从容。</p><div class="balance-v2"><div><span>会员储值余额</span><strong>${money(active.reduce((sum,m)=>sum+m.balance,0))}</strong></div><span class="balance-motif" aria-hidden="true">${v2Icon('spark')}</span><div class="balance-caption"><span>当前会员可用储值总额</span><span class="balance-brand">Best Dream</span></div></div></div>${rechargeRanking()}</section><section class="member-panel member-workspace"><div class="member-workspace-heading"><div><h2>会员档案</h2><p>每一位客人，都值得用心记得。</p></div><button id="new-member" class="primary"><span aria-hidden="true">＋</span> 新增会员</button></div><div class="toolbar member-searchbar"><label class="member-search"><span class="sr-only">查找会员</span>${v2Icon('search')}<input id="search" type="search" placeholder="搜索姓名或手机号" aria-label="搜索会员" value="${esc(S.query)}"></label><div class="member-heading-actions"><button id="payment-records">${v2Icon('history')}<span>消费同步记录</span></button><button id="auto-refresh" class="quiet icon-button" aria-label="刷新同步结果和会员余额" title="刷新余额">${v2Icon('refresh')}</button></div></div><div class="member-list-meta"><div class="segments">${[['all',`全部会员 <span>${active.length}</span>`],['birthday',`本月生日 <span>${birthdays}</span>`],...(isAdmin()?[['deleted','已删除']]:[])].map(([k,n])=>`<button data-filter="${k}" aria-pressed="${S.filter===k}" class="${S.filter===k?'active':''}">${n}</button>`).join('')}</div><span class="list-hint">点击姓名查看完整资料</span></div>${memberNotice()}<div id="member-table"></div><div class="member-workspace-footer">${paymentGuide()}</div></section>`;
 const ranking=$('.ranking-v2');ranking.ontoggle=()=>{S.rankingOpen=ranking.open;};
 const guidance=$('.member-workspace-footer');guidance.className='member-workflow-v2';$('.member-searchbar').after(guidance);
 const guideDetails=guidance.querySelector('details');guideDetails.open=!!S.guideOpen;
 guideDetails.querySelector('summary').textContent='充值在会员台；百居易确认储值收款后自动扣余额';
 guideDetails.ontoggle=()=>{S.guideOpen=guideDetails.open;};
 $('#payment-records').setAttribute('aria-label','消费同步记录');
 $('#new-member').onclick=()=>memberDialog();$('#search').oninput=e=>{S.query=e.target.value;memberTable();};
 $$('[data-filter]').forEach(b=>b.onclick=()=>{S.filter=b.dataset.filter;render();});
 memberTable();bindAuto();$('#payment-records').onclick=showPaymentRecords;
 if($('#show-issues'))$('#show-issues').onclick=showMemberIssues;
}

const v2BaseMemberTable=memberTable;
memberTable=function(){
 v2BaseMemberTable();
 $$('.member-desktop tbody tr').forEach(row=>{
  const cell=row.querySelector('td'),button=cell.querySelector('.member-name');
  const identity=document.createElement('div');identity.className='member-identity-v2';
  const avatar=document.createElement('span');avatar.className='member-avatar-v2';avatar.setAttribute('aria-hidden','true');avatar.innerHTML=v2Initial(button.textContent);
  const text=document.createElement('div');while(cell.firstChild)text.append(cell.firstChild);
  identity.append(avatar,text);cell.append(identity);
 });
 $$('.member-mobile .member-card-main>div:first-child').forEach(cell=>{
  const button=cell.querySelector('.member-name'),avatar=document.createElement('span');
  avatar.className='member-avatar-v2';avatar.setAttribute('aria-hidden','true');avatar.innerHTML=v2Initial(button.textContent);
  cell.prepend(avatar);
 });
};

openModal=function(title,body){v2BaseModal(title,body);$('#modal').classList.remove('recharge-modal-v2');};
transactionDialog=function(member,kind){
 v2BaseRecharge(member,kind);if(kind!=='recharge')return;
 $('#modal').classList.add('recharge-modal-v2');
 const form=$('#transaction-form'),fieldsets=Array.from(form.querySelectorAll('fieldset'));
 const left=document.createElement('div'),right=document.createElement('div');left.className='recharge-main-v2';right.className='recharge-side-v2';
 fieldsets[0].before(left);left.append(fieldsets[0],fieldsets[1]);right.append(fieldsets[2],form.querySelector('.recharge-note'));left.after(right);
 const calculation=document.createElement('div');calculation.className='recharge-calculation';calculation.innerHTML='<span>充值后余额</span><strong></strong>';fieldsets[0].append(calculation);
 const content=document.createElement('div');content.className='recharge-content-v2';
 const footer=document.createElement('footer');footer.className='recharge-footer-v2';
 if(form.querySelector('.warning'))content.append(form.querySelector('.warning'));
 content.append(left,right);footer.append(form.querySelector(':scope > .muted'),form.querySelector('.recharge-submit'));form.replaceChildren(content,footer);
 const update=()=>{
  const value=form.elements.amount.value.trim(),valid=/^\d+(\.\d{1,2})?$/.test(value)&&Number(value)>0;
  calculation.querySelector('strong').textContent=valid?money(member.balance+Math.round(Number(value)*100)):'—';
  $$('[data-amount]').forEach(b=>{const selected=valid&&Number(b.dataset.amount)===Number(value);b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected));});
 };
 form.elements.amount.addEventListener('input',update);$$('[data-amount]').forEach(b=>b.addEventListener('click',update));update();
};

authView=function(){
 v2BaseAuth();const auth=$('.auth');
 const frame=document.createElement('div');frame.className='login-frame-v2';
 const story=document.createElement('aside');story.className='login-story-v2';story.innerHTML=`<span class="login-wordmark">Best Dream</span><div class="dream-orbit" aria-hidden="true"><i></i><i></i><i></i>${v2Icon('spark')}</div><h2>让服务，更从容。</h2><p>用心记得每一位客人，<br>清楚记录每一笔储值。</p><small>酒店会员服务工作台</small>`;
 auth.before(frame);frame.append(story,auth);
};

